//
// Purpose: Hand-written Python module "_workshop" exposing Steam Workshop
//			functions to Python. Not generated by Py++, because the newer
//			Steamworks headers can't be parsed together with the old ones.
//			Registered in CSrcPython::CSrcPython (srcpy.cpp).
//
//=============================================================================//

#include "cbase.h"
#include "srcpy.h"
#include "wars_workshop.h"
#include "wars_workshop_steam.h"

// memdbgon must be the last include file in a .cpp file!!!
#include "tier0/memdbgon.h"

namespace bp = boost::python;

//-----------------------------------------------------------------------------
// Purpose:
//-----------------------------------------------------------------------------
static bp::object PyCallResultToDict( const WorkshopCallResult_t &result )
{
	bp::dict d;
	d["iofailure"] = result.bIOFailure;
	d["result"] = result.result;
	d["publishedfileid"] = result.item;
	d["needslegalagreement"] = result.bNeedsLegalAgreement;
	return d;
}

static bp::object PyGetCreateItemResult( WorkshopAPICall_t call )
{
	WorkshopCallResult_t result;
	if( !WarsWorkshopSteam_GetCreateItemResult( call, result ) )
		return bp::object();
	return PyCallResultToDict( result );
}

static bp::object PyGetSubmitItemUpdateResult( WorkshopAPICall_t call )
{
	WorkshopCallResult_t result;
	if( !WarsWorkshopSteam_GetSubmitItemUpdateResult( call, result ) )
		return bp::object();
	return PyCallResultToDict( result );
}

static bool PySetItemTags( WorkshopUpdateHandle_t handle, bp::list tags )
{
	CUtlVector< CUtlString > tagStrings;
	CUtlVector< const char * > tagPointers;
	int numTags = bp::len( tags );
	for( int i = 0; i < numTags; i++ )
		tagStrings.AddToTail( CUtlString( bp::extract< const char * >( tags[i] ) ) );
	for( int i = 0; i < tagStrings.Count(); i++ )
		tagPointers.AddToTail( tagStrings[i].Get() );
	return WarsWorkshopSteam_SetItemTags( handle, tagPointers.Base(), tagPointers.Count() );
}

static bp::tuple PyGetItemUpdateProgress( WorkshopUpdateHandle_t handle )
{
	unsigned long long bytesProcessed, bytesTotal;
	int status = WarsWorkshopSteam_GetItemUpdateProgress( handle, &bytesProcessed, &bytesTotal );
	return bp::make_tuple( status, bytesProcessed, bytesTotal );
}

static bp::list PyGetSubscribedItems()
{
	CUtlVector< WorkshopItemId_t > items;
	items.SetCount( WarsWorkshopSteam_GetNumSubscribedItems() );
	if( items.Count() > 0 )
		items.SetCount( WarsWorkshopSteam_GetSubscribedItems( items.Base(), items.Count() ) );

	bp::list result;
	for( int i = 0; i < items.Count(); i++ )
		result.append( items[i] );
	return result;
}

static bp::object PyGetItemInstallFolder( WorkshopItemId_t item )
{
	char szFolder[MAX_PATH];
	if( !WarsWorkshopSteam_GetItemInstallInfo( item, szFolder, sizeof( szFolder ), NULL, NULL ) )
		return bp::object();
	return bp::object( szFolder );
}

static void PyRefreshSubscribedItems()
{
	WarsWorkshop().RefreshSubscribedItems();
}

BOOST_PYTHON_MODULE(_workshop)
{
	bp::def( "IsAvailable", WarsWorkshopSteam_IsAvailable );
	bp::def( "GetError", WarsWorkshopSteam_GetError );

	// Subscribed items
	bp::def( "GetSubscribedItems", PyGetSubscribedItems );
	bp::def( "GetItemState", WarsWorkshopSteam_GetItemState );
	bp::def( "GetItemInstallFolder", PyGetItemInstallFolder );
	bp::def( "RefreshSubscribedItems", PyRefreshSubscribedItems );

	// Publishing
	bp::def( "CreateItem", WarsWorkshopSteam_CreateItem );
	bp::def( "GetCreateItemResult", PyGetCreateItemResult );
	bp::def( "StartItemUpdate", WarsWorkshopSteam_StartItemUpdate );
	bp::def( "SetItemTitle", WarsWorkshopSteam_SetItemTitle );
	bp::def( "SetItemDescription", WarsWorkshopSteam_SetItemDescription );
	bp::def( "SetItemVisibility", WarsWorkshopSteam_SetItemVisibility );
	bp::def( "SetItemTags", PySetItemTags );
	bp::def( "SetItemContent", WarsWorkshopSteam_SetItemContent );
	bp::def( "SetItemPreview", WarsWorkshopSteam_SetItemPreview );
	bp::def( "SubmitItemUpdate", WarsWorkshopSteam_SubmitItemUpdate );
	bp::def( "GetItemUpdateProgress", PyGetItemUpdateProgress );
	bp::def( "GetSubmitItemUpdateResult", PyGetSubmitItemUpdateResult );

	bp::scope().attr( "API_CALL_INVALID" ) = WORKSHOP_API_CALL_INVALID;
	bp::scope().attr( "UPDATE_HANDLE_INVALID" ) = WORKSHOP_UPDATE_HANDLE_INVALID;

	bp::scope().attr( "ITEM_STATE_SUBSCRIBED" ) = (int)WORKSHOP_ITEM_SUBSCRIBED;
	bp::scope().attr( "ITEM_STATE_INSTALLED" ) = (int)WORKSHOP_ITEM_INSTALLED;
	bp::scope().attr( "ITEM_STATE_NEEDS_UPDATE" ) = (int)WORKSHOP_ITEM_NEEDS_UPDATE;
	bp::scope().attr( "ITEM_STATE_DOWNLOADING" ) = (int)WORKSHOP_ITEM_DOWNLOADING;
	bp::scope().attr( "ITEM_STATE_DOWNLOAD_PENDING" ) = (int)WORKSHOP_ITEM_DOWNLOAD_PENDING;

	bp::scope().attr( "VISIBILITY_PUBLIC" ) = (int)WORKSHOP_VISIBILITY_PUBLIC;
	bp::scope().attr( "VISIBILITY_FRIENDSONLY" ) = (int)WORKSHOP_VISIBILITY_FRIENDSONLY;
	bp::scope().attr( "VISIBILITY_PRIVATE" ) = (int)WORKSHOP_VISIBILITY_PRIVATE;
	bp::scope().attr( "VISIBILITY_UNLISTED" ) = (int)WORKSHOP_VISIBILITY_UNLISTED;

	bp::scope().attr( "UPDATE_STATUS_INVALID" ) = (int)WORKSHOP_UPDATE_INVALID;
	bp::scope().attr( "UPDATE_STATUS_PREPARING_CONFIG" ) = (int)WORKSHOP_UPDATE_PREPARING_CONFIG;
	bp::scope().attr( "UPDATE_STATUS_PREPARING_CONTENT" ) = (int)WORKSHOP_UPDATE_PREPARING_CONTENT;
	bp::scope().attr( "UPDATE_STATUS_UPLOADING_CONTENT" ) = (int)WORKSHOP_UPDATE_UPLOADING_CONTENT;
	bp::scope().attr( "UPDATE_STATUS_UPLOADING_PREVIEW" ) = (int)WORKSHOP_UPDATE_UPLOADING_PREVIEW;
	bp::scope().attr( "UPDATE_STATUS_COMMITTING" ) = (int)WORKSHOP_UPDATE_COMMITTING;

	bp::scope().attr( "RESULT_OK" ) = 1;
}
